export const LOGO_EMPRESA_ALTO = 125;

/**
 * Logos de las aerolíneas del manifiesto, INCRUSTADOS (PNG pequeño en data URI, 360 px de ancho máximo):
 * no dependen de ninguna dirección externa, así la impresión y el Excel salen siempre con logo.
 * Fuente: Wikimedia Commons (Latam-logo_.png, AmeriJet_International_logo.png, FedEx_Express.svg,
 * Kalitta_Air_logo.svg, Air_Canada_2017.svg, UPS_Logo_Shield_2017.svg, KLM_logo.svg, Abx_Air_logo.svg,
 * Logo_wordmark_Atlas_Air_(2019).png), reducidos a PNG. UNITED y CARGOJET no tienen una versión estable
 * en Commons: llevan un logotipo tipográfico limpio con el nombre. La clave es `AerolineaManifiesto.clave`.
 */
export interface LogoIncrustado {
  dataUrl: string;
  ancho: number;
  alto: number;
}

